package com.gamehubstore.promotion_mscv.services;
import com.gamehubstore.promotion_mscv.models.*; import com.gamehubstore.promotion_mscv.repositories.*;
import org.slf4j.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.math.*; import java.time.LocalDate; import java.util.*;
@Service public class PromotionService {
 private static final Logger log=LoggerFactory.getLogger(PromotionService.class); private final PromotionRepository repo; private final PromotionReservationRepository reservations;
 public PromotionService(PromotionRepository repo,PromotionReservationRepository reservations){this.repo=repo;this.reservations=reservations;}
 public List<Promotion> all(){return repo.findAll();} public List<Promotion> active(){return repo.findByActiveTrue();}
 public Promotion byId(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Promoción no encontrada: "+id));}
 public Promotion byCode(String code){return repo.findByCodeIgnoreCase(code).orElseThrow(()->new NoSuchElementException("Cupón no encontrado"));}
 @Transactional public Promotion create(Promotion p){validate(p);if(repo.existsByCodeIgnoreCase(p.getCode()))throw new IllegalArgumentException("El código ya existe");p.setCode(p.getCode().trim().toUpperCase(Locale.ROOT));p.setUsedCount(0);log.info("Creando promoción código={}",p.getCode());return repo.save(p);}
 @Transactional public Promotion update(Long id,Promotion p){Promotion old=byId(id);long activeReservations=reservations.countByCodeIgnoreCaseAndStatus(old.getCode(),"RESERVADA");if(!old.getCode().equalsIgnoreCase(p.getCode())&&activeReservations>0)throw new IllegalStateException("No se puede cambiar el código mientras hay órdenes que lo reservaron");if(!old.getCode().equalsIgnoreCase(p.getCode())&&repo.existsByCodeIgnoreCase(p.getCode()))throw new IllegalArgumentException("El código ya existe");validate(p);if(p.getMaxUses()!=null&&p.getMaxUses()<old.getUsedCount()+activeReservations)throw new IllegalArgumentException("El máximo de usos no puede quedar bajo los usos confirmados o reservados");p.setCode(p.getCode().trim().toUpperCase(Locale.ROOT));return repo.save(copyFields(p,old));}
 private Promotion copyFields(Promotion p,Promotion old){old.setCode(p.getCode());old.setType(p.getType());old.setValue(p.getValue());old.setStartDate(p.getStartDate());old.setEndDate(p.getEndDate());old.setMinimumAmount(p.getMinimumAmount());old.setMaxUses(p.getMaxUses());old.setActive(p.isActive());return old;}
 private void validate(Promotion p){if(p.getType()!=null&&!List.of("PORCENTAJE","MONTO").contains(p.getType().toUpperCase(Locale.ROOT)))throw new IllegalArgumentException("El tipo debe ser PORCENTAJE o MONTO");if(p.getStartDate()!=null&&p.getEndDate()!=null&&p.getEndDate().isBefore(p.getStartDate()))throw new IllegalArgumentException("La fecha de término debe ser posterior al inicio");if("PORCENTAJE".equalsIgnoreCase(p.getType())&&p.getValue()!=null&&p.getValue().compareTo(new BigDecimal("100"))>0)throw new IllegalArgumentException("El descuento porcentual no puede superar 100");}
 @Transactional public void deactivate(Long id){Promotion p=byId(id);p.setActive(false);repo.save(p);}
 // Consulta pura: no modifica usedCount ni reserva el cupo.
 @Transactional(readOnly=true) public BigDecimal validateAndCalculate(String code,BigDecimal total){Promotion p=byCode(code);checkEligible(p,total);return calculate(p,total);}
 @Transactional public PromotionReservation reserve(Long orderId,String code,BigDecimal total){if(orderId==null)throw new IllegalArgumentException("orderId es obligatorio");var found=reservations.findByOrderId(orderId);if(found.isPresent()){PromotionReservation existing=found.get();if(!existing.getCode().equalsIgnoreCase(code))throw new IllegalArgumentException("La orden ya reservó otro cupón");if("LIBERADA".equals(existing.getStatus()))throw new IllegalStateException("La reserva del cupón fue liberada");return existing;}
  Promotion p=repo.findByCodeForUpdate(code).orElseThrow(()->new NoSuchElementException("Cupón no encontrado"));
  // Recheck after acquiring the promotion lock so concurrent retries for one order stay idempotent.
  var concurrent=reservations.findByOrderId(orderId);if(concurrent.isPresent()){if(!concurrent.get().getCode().equalsIgnoreCase(code))throw new IllegalArgumentException("La orden ya reservó otro cupón");if("LIBERADA".equals(concurrent.get().getStatus()))throw new IllegalStateException("La reserva del cupón fue liberada");return concurrent.get();}
  checkEligible(p,total);PromotionReservation reservation=new PromotionReservation();reservation.setOrderId(orderId);reservation.setCode(p.getCode());reservation.setDiscount(calculate(p,total));reservation.setStatus("RESERVADA");log.info("Cupón reservado orderId={} code={}",orderId,p.getCode());return reservations.save(reservation);}
 @Transactional public PromotionReservation commit(Long orderId){PromotionReservation r=reservations.findByOrderIdForUpdate(orderId).orElse(null);if(r==null)return null;if("CONFIRMADA".equals(r.getStatus()))return r;if(!"RESERVADA".equals(r.getStatus()))throw new IllegalStateException("No se puede confirmar una reserva "+r.getStatus());Promotion p=repo.findByCodeForUpdate(r.getCode()).orElseThrow(()->new NoSuchElementException("Cupón no encontrado"));p.setUsedCount(p.getUsedCount()+1);repo.save(p);r.setStatus("CONFIRMADA");r.setUpdatedAt(java.time.LocalDateTime.now());log.info("Uso de cupón confirmado orderId={} code={}",orderId,r.getCode());return reservations.save(r);}
 @Transactional public PromotionReservation release(Long orderId){PromotionReservation r=reservations.findByOrderIdForUpdate(orderId).orElse(null);if(r==null||"LIBERADA".equals(r.getStatus()))return r;if("CONFIRMADA".equals(r.getStatus()))throw new IllegalStateException("El cupón ya fue confirmado y requiere política explícita de reembolso");repo.findByCodeForUpdate(r.getCode()).orElseThrow(()->new NoSuchElementException("Cupón no encontrado"));r.setStatus("LIBERADA");r.setUpdatedAt(java.time.LocalDateTime.now());log.info("Reserva de cupón liberada orderId={}",orderId);return reservations.save(r);}
 private void checkEligible(Promotion p,BigDecimal total){LocalDate today=LocalDate.now();if(!p.isActive()||today.isBefore(p.getStartDate())||today.isAfter(p.getEndDate()))throw new IllegalArgumentException("Promoción fuera de vigencia");if(total==null||total.signum()<0||total.compareTo(p.getMinimumAmount())<0)throw new IllegalArgumentException("No cumple el monto mínimo");long held=reservations.countByCodeIgnoreCaseAndStatus(p.getCode(),"RESERVADA");if(p.getMaxUses()!=null&&p.getUsedCount()+held>=p.getMaxUses())throw new IllegalArgumentException("Cupón agotó sus usos disponibles");}
 private BigDecimal calculate(Promotion p,BigDecimal total){BigDecimal amount="PORCENTAJE".equalsIgnoreCase(p.getType())?total.multiply(p.getValue()).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP):p.getValue();return amount.min(total);}
}
